{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Integrative care for everyday life</title>
  <meta name="description" content="A holistic, practical approach to health that connects the pieces of daily life to lasting routines.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="split-diagonal">
  <header class="site-header">
    <div class="brand">
      <svg width="48" height="48" viewBox="0 0 100 100" aria-hidden="true">
        <rect width="100" height="100" rx="14" fill="#f3f6f2" />
        <circle cx="50" cy="38" r="18" fill="#3b6b57" opacity="0.95" />
        <path d="M20 82 C40 70,60 70,80 82" stroke="#6aa982" stroke-width="6" fill="none" stroke-linecap="round" />
      </svg>
      <div class="titles">
        <strong class="name">{{BUSINESS_NAME}}</strong>
        <small class="tag">{{TAGLINE}}</small>
      </div>
    </div>
    <nav class="nav">
      <a href="index.html">Welcome</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Conditions</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Story</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
    <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    <button class="try-btn" id="openExercise">Try it now</button>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <div class="hero-inner">
        <h1>Guided, sensible steps to rebuild your days around what matters.</h1>
        <p class="lead">Practical integrative health support that listens to the rhythms of your life and builds simple, reliable routines. We help you decide what to try next — with compassion and a plan.</p>
        <div class="hero-actions">
          <a class="primary" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
          <button class="secondary" id="openInventory">Take the whole-person check</button>
        </div>
      </div>
      <div class="hero-pattern" aria-hidden="true"></div>
    </section>

    <!-- What to expect (moved ahead for this layout) -->
    <section class="what-to-expect">
      <h2>What a first session looks like</h2>
      <ol>
        <li><strong>Story first:</strong> We map recent changes and current priorities.</li>
        <li><strong>Inventory-driven focus:</strong> Targeted measurement of sleep, movement, stress, digestion, relationships, and routines.</li>
        <li><strong>Simple next steps:</strong> One to three practical experiments tailored to your schedule.</li>
      </ol>
      <p class="note">Appointments are educational and supportive. Not a substitute for emergency care.</p>
    </section>

    <!-- Gallery of offerings -->
    <section class="gallery">
      <h2>Programs and sessions</h2>
      <div class="cards">
        <article>
          <h3>Balance Plan — Starter</h3>
          <p>Four visits over eight weeks. Focused on sleep, stress tools, and daily rhythm building.</p>
          <div class="price">From $320</div>
        </article>
        <article>
          <h3>Renew Track — Stabilize</h3>
          <p>Eight visits plus group check-ins. Adds guided breathwork and mindful journaling routines.</p>
          <div class="price">From $720</div>
        </article>
        <article>
          <h3>Ongoing Support — Monthly</h3>
          <p>Monthly maintenance visits and messaging for graduated adjustments.</p>
          <div class="price">From $140/month</div>
        </article>
      </div>
    </section>

    <!-- Objections / concerns -->
    <section class="objections">
      <h2>Questions people often have</h2>
      <details>
        <summary>Is this a medical diagnosis?</summary>
        <p>We provide educational assessment and supportive planning. For urgent or life-threatening concerns, seek immediate medical care.</p>
      </details>
      <details>
        <summary>Will this interfere with my current treatments?</summary>
        <p>We coordinate with existing care and aim to complement, not replace, your medical providers.</p>
      </details>
      <details>
        <summary>How quickly will I see change?</summary>
        <p>Changes are often subtle and cumulative. We emphasize measurable small experiments over quick fixes.</p>
      </details>
    </section>

    <!-- Whole-person inventory (interactive) -->
    <section class="inventory" id="inventorySection">
      <h2>Whole-person quick check</h2>
      <p>Select the areas where you feel friction — we'll suggest an agenda and a follow-up rhythm.</p>
      <form id="inventoryForm">
        <div class="checks">
          <label><input type="checkbox" name="areas" value="sleep"> Sleep & rest</label>
          <label><input type="checkbox" name="areas" value="energy"> Energy & fatigue</label>
          <label><input type="checkbox" name="areas" value="digestion"> Digestion & appetite</label>
          <label><input type="checkbox" name="areas" value="stress"> Stress & overwhelm</label>
          <label><input type="checkbox" name="areas" value="movement"> Movement & strength</label>
          <label><input type="checkbox" name="areas" value="mood"> Mood & emotional regulation</label>
          <label><input type="checkbox" name="areas" value="relationships"> Relationships & boundaries</label>
          <label><input type="checkbox" name="areas" value="work"> Work & daily organization</label>
        </div>
        <div class="form-actions">
          <button type="submit" class="primary">Generate agenda</button>
          <button type="button" class="secondary" id="clearInventory">Clear</button>
        </div>
      </form>
      <div id="inventoryOutput" class="inventory-output" aria-live="polite"></div>
    </section>

    <!-- CTA -->
    <section class="cta-strip">
      <div>
        <h3>Ready to try a small, sensible change?</h3>
        <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="link" href="book.html">See booking options</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div>
      <strong>{{BUSINESS_NAME}}</strong>
      <div>{{CITY}}, {{STATE}} · <a href="tel:{{PHONE}}">{{PHONE}}</a> · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
    <small>Educational, non-emergency services. Not a replacement for medical care.</small>
  </footer>

  <!-- Guided exercise modal -->
  <div class="modal" id="exerciseModal" aria-hidden="true">
    <div class="modal-body" role="dialog" aria-modal="true" aria-labelledby="exerciseTitle">
      <button class="modal-close" id="closeExercise">×</button>
      <h2 id="exerciseTitle">Try a short practice</h2>
      <p class="modal-lead">Choose one focused practice to ground the next five minutes. No experience required.</p>
      <div class="exercise-options">
        <button data-type="breath" class="ex-btn">Breathing practice</button>
        <button data-type="journaling" class="ex-btn">Two-minute journaling</button>
        <button data-type="intention" class="ex-btn">Set a brief intention</button>
      </div>
      <div id="exerciseArea" class="exercise-area"></div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
